import ast

def validate_node(node):
    if isinstance(node, ast.Constant):
        return True
    if isinstance(node, ast.Name):
        return node.id in ("id", "name", "email")
    if isinstance(node, ast.Compare):
        return validate_node(node.left) and all(validate_node(c) for c in node.comparators)
    if isinstance(node, ast.BoolOp):
        return all(validate_node(v) for v in node.values)
    if isinstance(node, ast.UnaryOp):
        return isinstance(node.op, ast.Not) and validate_node(node.operand)
    return False

